.timeline {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0 28px;
  font-family: var(--bw-font-body);
  color: var(--bw-ink-steel);
}

.chip {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border: 1px solid var(--bw-tag-border);
  background: var(--bw-tag-bg);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-deep-steel);
}

.clearFilter {
  border: none;
  background: none;
  padding: 0;
  font-size: var(--bw-size-label);
  line-height: 1;
  color: var(--bw-steel-mist);
  cursor: pointer;
}

.clearFilter:hover {
  color: var(--bw-danger);
}

.clearFilter:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: 1px;
}

.serverToggle {
  align-self: flex-start;
  border: none;
  background: none;
  padding: 0;
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
  cursor: pointer;
  text-decoration: underline;
}

.serverToggle:hover {
  color: var(--bw-ink-steel);
}

.serverToggle:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: 1px;
}

.serverView {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-tag-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-ink-steel-soft);
  word-break: break-all;
}

.serverItem {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--bw-brass-border-soft);
}

.serverItem:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.serverKey {
  color: var(--bw-steel-mist);
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bubble {
  max-width: 78%;
  padding: 10px 14px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-body);
  line-height: 1.45;
}

.bubbleOwn {
  align-self: flex-end;
  background: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

.bubbleOther {
  align-self: flex-start;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  color: var(--bw-ink-steel);
}

.cardLine {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 6px 10px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-label);
}

.cardConsulta {
  background: var(--bw-tint-consulta);
}

.cardOferta {
  background: var(--bw-tint-oferta);
}

.cardSummary {
  color: var(--bw-ink-steel);
}

.cardState {
  color: var(--bw-text-secondary);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
}

.tag {
  align-self: flex-start;
  display: inline-block;
  padding: 2px 8px;
  border: 1px solid var(--bw-tag-border);
  background: var(--bw-tag-bg);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-deep-steel);
}

.retag {
  align-self: flex-start;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-hint);
  padding: 2px 6px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  color: var(--bw-input-text);
  background: var(--bw-cold-white);
}

.retag:focus {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.meta {
  display: flex;
  gap: 8px;
  font-size: var(--bw-size-hint);
  color: var(--bw-text-secondary);
}

.author {
  font-weight: 600;
}

.time {
  color: var(--bw-text-secondary);
}

.empty {
  margin: 0;
  color: var(--bw-text-secondary);
  font-size: var(--bw-size-label);
}

import { useState } from 'react';
import {
  TAB_TEXTS,
  referenceLabel,
  type ThreadReference,
  type ThreadReferenceOption,
  type TimelineEntry,
} from '../../lib/negotiation-rows';
import { ENCRYPTED_NOTICE, type ThreadItem } from '../../lib/thread-detail';
import { relativeTime } from '../../lib/threads';
import styles from './MessagesTimeline.module.css';

interface MessagesTimelineProps {
  entries: TimelineEntry[];
  allItems: ThreadItem[];
  references: ThreadReferenceOption[];
  filter: ThreadReference | null;
  onClearFilter: () => void;
  onRetag: (itemId: string, tag: ThreadReference | null) => void;
  authorOf: (item: ThreadItem) => string;
  now: Date;
}

/**
 * La pestaña Mensajes: la línea de tiempo del hilo.
 *
 * Presentacional: recibe las entradas ya calculadas por `messageTimeline` y las
 * pinta en el orden en que llegan. El único estado propio es el panel «Ver lo que
 * ve el servidor», cerrado al abrir. Cada mensaje libre muestra su etiqueta de
 * referencia (si la lleva) y, solo si es propio, el selector para cambiarla. El
 * texto del mensaje nunca se recalcula.
 */
export function MessagesTimeline({
  entries,
  allItems,
  references,
  filter,
  onClearFilter,
  onRetag,
  authorOf,
  now,
}: MessagesTimelineProps) {
  const [serverOpen, setServerOpen] = useState(false);

  return (
    <div className={styles.timeline}>
      {filter !== null && (
        <div className={styles.chip}>
          <span>{TAB_TEXTS.filterChip(referenceLabel(filter))}</span>
          <button
            type="button"
            aria-label={TAB_TEXTS.clearFilter}
            className={styles.clearFilter}
            onClick={onClearFilter}
          >
            ✕
          </button>
        </div>
      )}

      <button
        type="button"
        className={styles.serverToggle}
        aria-expanded={serverOpen}
        onClick={() => setServerOpen((open) => !open)}
      >
        {serverOpen ? TAB_TEXTS.serverViewClose : TAB_TEXTS.serverViewOpen}
      </button>

      {serverOpen && (
        <div data-testid="server-view" className={styles.serverView}>
          {allItems.map((item) => (
            <div key={item.id} className={styles.serverItem}>
              <div>
                <span className={styles.serverKey}>item_type</span>: {item.type}
              </div>
              <div>
                <span className={styles.serverKey}>part_number</span>: {item.partNumber ?? '—'}
              </div>
              <div>
                <span className={styles.serverKey}>brand</span>: {item.brand ?? '—'}
              </div>
              <div>
                <span className={styles.serverKey}>content_ciphertext</span>:{' '}
                {item.raw?.ciphertext ?? '—'}
              </div>
              <div>
                <span className={styles.serverKey}>content_iv</span>: {item.raw?.iv ?? '—'}
              </div>
            </div>
          ))}
        </div>
      )}

      {entries.length === 0 ? (
        <p className={styles.empty}>
          {filter ? TAB_TEXTS.noTimelineForReference : TAB_TEXTS.noMessages}
        </p>
      ) : (
        <ul className={styles.list}>
          {entries.map((entry) => {
            const item = entry.item;
            const isMessage = item.type === 'MENSAJE';
            const content = item.content;
            const text = content && content.kind === 'MENSAJE' ? content.text : ENCRYPTED_NOTICE;
            const tag =
              isMessage && item.partNumber && item.brand
                ? referenceLabel({ partNumber: item.partNumber, brand: item.brand })
                : null;
            const currentTag = tag ?? TAB_TEXTS.generalConversation;

            return (
              <li
                key={item.id}
                data-testid="thread-item"
                data-item-id={item.id}
                className={styles.item}
              >
                {isMessage ? (
                  <div
                    className={`${styles.bubble ?? ''} ${
                      item.isOwn ? (styles.bubbleOwn ?? '') : (styles.bubbleOther ?? '')
                    }`.trim()}
                  >
                    {text}
                  </div>
                ) : (
                  <div
                    className={`${styles.cardLine ?? ''} ${
                      item.type === 'CONSULTA' ? (styles.cardConsulta ?? '') : (styles.cardOferta ?? '')
                    }`.trim()}
                  >
                    <span className={styles.cardSummary}>{entry.summary}</span>
                    {entry.stateLabel !== null && (
                      <span className={styles.cardState}>{entry.stateLabel}</span>
                    )}
                  </div>
                )}

                {tag !== null && (
                  <span data-testid="message-tag" className={styles.tag}>
                    {tag}
                  </span>
                )}

                {isMessage && item.isOwn && (
                  <select
                    aria-label={TAB_TEXTS.retagLabel}
                    className={styles.retag}
                    value={currentTag}
                    onChange={(e) => {
                      const value = e.target.value;
                      if (value === TAB_TEXTS.generalConversation) {
                        onRetag(item.id, null);
                        return;
                      }
                      const ref = references.find((r) => r.label === value);
                      if (ref) onRetag(item.id, { partNumber: ref.partNumber, brand: ref.brand });
                    }}
                  >
                    <option value={TAB_TEXTS.generalConversation}>
                      {TAB_TEXTS.generalConversation}
                    </option>
                    {references.map((r) => (
                      <option key={r.label} value={r.label}>
                        {r.label}
                      </option>
                    ))}
                  </select>
                )}

                <div className={styles.meta}>
                  <span className={styles.author}>{authorOf(item)}</span>
                  <span className={styles.time}>{relativeTime(item.createdAt, now)}</span>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

